use super::*;
use std::time::{Instant,Duration};
pub struct Device{client_id:String,code:String,expires:Instant,next:Instant,interval:u64}
const BASE:&str="https://login.microsoftonline.com/consumers/oauth2/v2.0";
fn val<'a>(v:&'a Value,k:&str)->R<&'a str>{v[k].as_str().ok_or_else(||format!("Missing authentication field: {k}"))}
pub fn start(app:&AppHandle,id:&str)->R<Value>{if id.trim().is_empty(){return Err("Set your approved public-client application ID in Settings".into())}let c=game::client()?;let v:Value=c.post(format!("{BASE}/devicecode")).form(&[("client_id",id),("scope","XboxLive.signin offline_access")]).send().map_err(err)?.error_for_status().map_err(err)?.json().map_err(err)?;let code=val(&v,"device_code")?.to_owned();let key=val(&v,"user_code")?.to_owned();let url=val(&v,"verification_uri")?;if !url.starts_with("https://"){return Err("Invalid verification URL".into())}let interval=v["interval"].as_u64().unwrap_or(5).max(5);let now=Instant::now();app.state::<Runtime>().devices.lock().unwrap().insert(key.clone(),Device{client_id:id.into(),code,expires:now+Duration::from_secs(v["expires_in"].as_u64().unwrap_or(900)),next:now+Duration::from_secs(interval),interval});let _=open::that(url);Ok(json!({"session":key,"code":key,"url":url,"interval":interval}))}
pub fn poll(app:&AppHandle,key:&str)->R<Value>{let state=app.state::<Runtime>();let (id,code)={let mut ds=state.devices.lock().unwrap();let d=ds.get_mut(key).ok_or("Login session expired")?;let now=Instant::now();if now>=d.expires{return Err("Login session expired".into())}if now<d.next{return Ok(json!({"pending":true,"interval":d.interval}))}d.next=now+Duration::from_secs(d.interval);(d.client_id.clone(),d.code.clone())};let c=game::client()?;let v:Value=c.post(format!("{BASE}/token")).form(&[("grant_type","urn:ietf:params:oauth:grant-type:device_code"),("client_id",&id),("device_code",&code)]).send().map_err(err)?.json().map_err(err)?;if let Some(e)=v["error"].as_str(){if e=="authorization_pending"||e=="slow_down"{let mut ds=state.devices.lock().unwrap();let d=ds.get_mut(key).ok_or("Login session expired")?;if e=="slow_down"{d.interval+=5;d.next=Instant::now()+Duration::from_secs(d.interval)}return Ok(json!({"pending":true,"interval":d.interval}))}return Err(format!("Microsoft login: {e}"))}state.devices.lock().unwrap().remove(key);let ms=val(&v,"access_token")?;let x:Value=c.post("https://user.auth.xboxlive.com/user/authenticate").json(&json!({"Properties":{"AuthMethod":"RPS","SiteName":"user.auth.xboxlive.com","RpsTicket":format!("d={ms}")},"RelyingParty":"http://auth.xboxlive.com","TokenType":"JWT"})).send().map_err(err)?.error_for_status().map_err(err)?.json().map_err(err)?;let xs:Value=c.post("https://xsts.auth.xboxlive.com/xsts/authorize").json(&json!({"Properties":{"SandboxId":"RETAIL","UserTokens":[val(&x,"Token")?]},"RelyingParty":"rp://api.minecraftservices.com/","TokenType":"JWT"})).send().map_err(err)?.error_for_status().map_err(err)?.json().map_err(err)?;let hash=xs["DisplayClaims"]["xui"][0]["uhs"].as_str().ok_or("Xbox user hash missing")?;let mc:Value=c.post("https://api.minecraftservices.com/authentication/login_with_xbox").json(&json!({"identityToken":format!("XBL3.0 x={hash};{}",val(&xs,"Token")?)})).send().map_err(err)?.error_for_status().map_err(err)?.json().map_err(err)?;let token=val(&mc,"access_token")?;let profile:Value=c.get("https://api.minecraftservices.com/minecraft/profile").bearer_auth(token).send().map_err(err)?.error_for_status().map_err(|_|"Minecraft profile unavailable: check Java Edition ownership and app approval".to_string())?.json().map_err(err)?;let uid=val(&profile,"id")?;state.tokens.lock().unwrap().insert(uid.into(),token.into());Ok(json!({"pending":false,"account":{"id":uid,"name":val(&profile,"name")?,"type":"Microsoft"}}))}
